select 'AK-JREXJ' as code, (select count(*) from public.workbook_sections where version_id = '0888093a-4fab-51b2-aca1-8f494ca762af') as sections, (select published_at from public.workbook_versions where id = '0888093a-4fab-51b2-aca1-8f494ca762af') as published_at, (select status from public.workbooks where id = 'e6e4c5f4-a1d7-5378-b8dd-c0b87e7d822d') as status;
